// migrate.figma.js, generated by pipeline/09_migrate.py. Do not edit: run the Python again.
// Brings the variables of the file it runs in to the new version of the library, keeping identities:
// renames in place (layers stay bound), updates values, creates only what is new, deletes nothing.
// DRY RUN by default: it reports and changes nothing. Set APPLY = true to apply, on a copy first.
const APPLY = false;
const PLAN = /*PLAN*/null;

const rgba = (hex) => {
  const h = hex.replace("#", "");
  const n = (i) => parseInt(h.slice(i, i + 2), 16) / 255;
  return { r: n(0), g: n(2), b: n(4), a: h.length === 8 ? n(6) : 1 };
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const report = { apply: APPLY, done: [], alreadyThere: 0, notFound: [], review: PLAN.variables.review };

const cols = await figma.variables.getLocalVariableCollectionsAsync();
const vars = await figma.variables.getLocalVariablesAsync();
const colById = new Map(cols.map((c) => [c.id, c]));
const colByName = new Map(cols.map((c) => [c.name, c]));
const colName = (v) => (colById.get(v.variableCollectionId) || {}).name;
const byId = new Map(vars.map((v) => [v.id, v]));
const byName = new Map(vars.map((v) => [colName(v) + "/" + v.name, v]));
const act = (what, fn) => { report.done.push(what); if (APPLY) fn(); };

// 1. Collections: rename, create, add modes.
for (const r of PLAN.collections.rename) {
  const c = colById.get(r.id) || colByName.get(r.from);
  if (!c) { if (!colByName.get(r.to)) report.notFound.push("collection " + r.from); continue; }
  if (c.name === r.to) { report.alreadyThere++; continue; }
  act(`rename collection ${r.from} -> ${r.to}`, () => { c.name = r.to; });
  colByName.set(r.to, c);
}
for (const c of PLAN.collections.create) {
  if (colByName.get(c.name)) { report.alreadyThere++; continue; }
  act(`create collection ${c.name} (${c.modes.join(", ")})`, () => {
    const made = figma.variables.createVariableCollection(c.name);
    made.renameMode(made.modes[0].modeId, c.modes[0]);
    for (const m of c.modes.slice(1)) made.addMode(m);
    colByName.set(c.name, made);
    colById.set(made.id, made);
  });
}
for (const m of PLAN.collections.addModes) {
  const c = colByName.get(m.collection);
  if (!c) { report.notFound.push("collection " + m.collection); continue; }
  if (c.modes.some((x) => x.name === m.mode)) { report.alreadyThere++; continue; }
  act(`add mode ${m.mode} to ${m.collection}`, () => c.addMode(m.mode));
}

// 2. Variables: rename in place, then create what is new.
const find = (id, collection, name) => byId.get(id) || byName.get(collection + "/" + name);
// Gone variables whose name is now used by another one are moved out of the way first: _review/<name>.
for (const r of PLAN.variables.review) {
  if (!r.parkAs) continue;
  const v = byId.get(r.id) || byName.get(r.collection + "/" + r.name);
  if (!v || v.id === r.nameNowUsedBy) { report.alreadyThere++; continue; }
  if (v.name === r.parkAs) { report.alreadyThere++; continue; }
  act(`move ${r.name} out of the way -> ${r.parkAs}`, () => { v.name = r.parkAs; });
  byName.delete(r.collection + "/" + r.name);
  byName.set(r.collection + "/" + r.parkAs, v);
}

// Renames run in two passes, through a temporary name, so a chain (h3 -> h5 while a new h3 is created, or
// a -> b while b -> c) never meets a name that is still taken. The old name is freed in the lookup at once.
const renames = [];
for (const r of PLAN.variables.rename) {
  const v = find(r.id, r.oldCollection, r.from) || byName.get(r.collection + "/" + r.to);
  if (!v) { report.notFound.push(`${r.oldCollection}/${r.from}`); continue; }
  if (v.name === r.to) { report.alreadyThere++; continue; }
  renames.push([r, v]);
  if (byName.get(r.oldCollection + "/" + r.from) === v) byName.delete(r.oldCollection + "/" + r.from);
}
renames.forEach(([r, v], i) => { if (APPLY) v.name = "__migrating__/" + i; });
for (const [r, v] of renames) {
  act(`rename ${r.from} -> ${r.to}`, () => { v.name = r.to; });
  byName.set(r.collection + "/" + r.to, v);
}
for (const c of PLAN.variables.create) {
  if (find(c.id, c.collection, c.name)) { report.alreadyThere++; continue; }
  act(`create ${c.collection}/${c.name}`, () => {
    const col = colByName.get(c.collection);
    const v = figma.variables.createVariable(c.name, col, c.type);
    byName.set(c.collection + "/" + c.name, v);
  });
}

// 3. Values, aliases, code names, descriptions, scopes. Aliases are found by their new name.
for (const u of PLAN.variables.update) {
  const v = find(u.id, u.collection, u.name);
  if (!v) { if (!APPLY && PLAN.variables.create.some((c) => c.collection === u.collection && c.name === u.name)) continue; report.notFound.push(`${u.collection}/${u.name}`); continue; }
  const col = colById.get(v.variableCollectionId) || colByName.get(u.collection);
  for (const [mode, x] of Object.entries(u.values || {})) {
    const m = col.modes.find((mm) => mm.name === mode);
    if (!m) { if (!APPLY) continue; report.notFound.push(`mode ${mode} in ${u.collection}`); continue; }
    let want;
    if (x.alias) {
      const t = byName.get(x.alias[0] + "/" + x.alias[1]);
      if (!t) { if (!APPLY) { report.done.push(`alias ${u.name} [${mode}] -> ${x.alias.join("/")}`); continue; } report.notFound.push("alias " + x.alias.join("/")); continue; }
      want = figma.variables.createVariableAlias(t);
    } else {
      want = typeof x.value === "string" && x.value.startsWith("#") ? rgba(x.value) : x.value;
    }
    const have = v.valuesByMode[m.modeId];
    const equal = want.type === "VARIABLE_ALIAS" ? have && have.id === want.id
      : typeof want === "object" ? have && ["r", "g", "b", "a"].every((k) => Math.abs((have[k] ?? 1) - want[k]) < 0.002) : typeof want === "number" ? typeof have === "number" && Math.abs(have - want) < 1e-3 : have === want; // Figma stores numbers as 32-bit floats
    if (equal) { report.alreadyThere++; continue; }
    act(`set ${u.collection}/${u.name} [${mode}]`, () => v.setValueForMode(m.modeId, want));
  }
  if ("codeSyntax" in u) {
    const want = u.codeSyntax || null;
    if ((v.codeSyntax.WEB || null) === want) report.alreadyThere++;
    else act(`code name ${u.name} -> ${want}`, () => want ? v.setVariableCodeSyntax("WEB", want) : v.removeVariableCodeSyntax("WEB"));
  }
  if ("description" in u) {
    if ((v.description || "") === (u.description || "")) report.alreadyThere++;
    else act(`description ${u.name}`, () => { v.description = u.description || ""; });
  }
  if ("scopes" in u && u.scopes) {
    if (same([...v.scopes].sort(), [...u.scopes].sort())) report.alreadyThere++;
    else act(`scopes ${u.name}`, () => { v.scopes = u.scopes; });
  }
}

return JSON.stringify({
  apply: report.apply,
  changes: report.done.length,
  alreadyThere: report.alreadyThere,
  notFound: report.notFound,
  toReview: report.review.length,
  needDecision: report.review.filter((r) => r.status === "needs a decision").map((r) => r.collection + "/" + r.name),
  sample: report.done.slice(0, 25),
});
